target.css:
:root {
  --ink: #19323c;
  --paper: #fffdf7;
  --line: #bdd1cc;
  --mint: #dff3e9;
  --mint-ink: #146b50;
  --coral: #fa7c63;
  --muted: #627a7d;
}

.claim-card,
.claim-card * {
  box-sizing: border-box;
}

.claim-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.claim-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  border-bottom: 1px dashed var(--line);
}

.header-copy p,
.bike-row h2,
.bike-row p {
  margin: 0;
}

.eyebrow,
.detail-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.event-name {
  margin-top: 3px !important;
  font-size: 14px;
  font-weight: 700;
}

.claim-number {
  padding: 6px 10px;
  color: var(--paper);
  background: var(--coral);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
}

.bike-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
}

.bike-icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  background: var(--mint);
  border-radius: 12px;
  font-size: 24px;
}

.bike-row h2 {
  font-size: 17px;
  line-height: 1.2;
}

.bike-meta {
  margin-top: 4px !important;
  color: var(--muted);
  font-size: 13px;
}

.details-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 12px;
}

.detail:first-child {
  padding-left: 0;
}

.detail:not(:last-child) {
  border-right: 1px solid var(--line);
}

.detail strong {
  font-size: 14px;
}

.claim-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  background: var(--mint);
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--mint-ink);
  font-size: 12px;
  font-weight: 700;
}

.status i {
  width: 8px;
  height: 8px;
  background: var(--mint-ink);
  border-radius: 50%;
}

button {
  padding: 7px 10px;
  color: var(--mint-ink);
  background: var(--paper);
  border: 1px solid var(--mint-ink);
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

